#pragma once

#include "cuda_compat.h"

namespace vllm {

template<typename T>
__inline__ __device__ T warpReduceSum(T val) {
#pragma unroll
  for (int mask = WARP_SIZE/2; mask > 0; mask >>= 1)
    val += VLLM_SHFL_XOR_SYNC(val, mask);
  return val;
}

__inline__ __device__ constexpr int _calculateLaneMask(int warp_size) {
  return warp_size - 1;
}

__inline__ __device__ constexpr int _calculateWidShift(int warp_size) {
  return 5 + (warp_size >> 6);
}

/* Calculate the sum of all elements in a block */
template<typename T>
__inline__ __device__ T blockReduceSum(T val) {
  __shared__ T shared[WARP_SIZE];
  int lane = threadIdx.x & (WARP_SIZE - 1);
  int wid = threadIdx.x / WARP_SIZE;

  // Intra-warp reduce
  val = warpReduceSum<T>(val);

  if (lane == 0)
    shared[wid] = val;

  __syncthreads();

  // Only the first warp reduces across warps
  T total = (threadIdx.x < ((blockDim.x + WARP_SIZE - 1) / WARP_SIZE)) ? shared[lane] : static_cast<T>(0);
  if (threadIdx.x < WARP_SIZE) {
    total = warpReduceSum<T>(total);
  }
  return total;
}

} // namespace vllm

