/* Calculate the sum of all elements in a block - optimized version */
template<typename T>
__inline__ __device__ T blockReduceSum(T val) {
  static __shared__ T shared[32];  // Use explicit size for better performance
  const int lane = threadIdx.x & 31;  // threadIdx.x % 32
  const int wid = threadIdx.x >> 5;   // threadIdx.x / 32 (faster than division)

  // Intra-warp reduce
  val = warpReduceSum<T>(val);

  // Write reduced value to shared memory
  if (lane == 0) {
    shared[wid] = val;
  }

  __syncthreads();

  // Final reduce across warps
  const int num_warps = (blockDim.x + 31) >> 5;
  val = (threadIdx.x < num_warps) ? shared[lane] : static_cast<T>(0);

  if (wid == 0) {
    val = warpReduceSum<T>(val);
  }

  return val;
}

